Bank.add("credit", [
  { id: "cr-01", lv: 2, trap: [null, "sign", null], q: "A loan covenant caps net debt/EBITDA at 4.0x. Which event is most likely to cause a breach?",
    o: ["A sharp fall in EBITDA after losing a major customer", "Refinancing the debt at the same principal with a longer maturity", "A rise in cash after selling a non-core asset", "A reduction in capital expenditure"],
    why: "The ratio rises when EBITDA falls. Losing a big customer can push it through 4.0x even if debt is unchanged.",
    x: ["Same principal means the same debt, so the ratio doesn't move.", "More cash reduces net debt, so the ratio falls.", "Lower capex frees up cash and reduces net debt; it doesn't touch EBITDA."] },
  { id: "cr-02", lv: 1, q: "In an insolvency, which claim is typically repaid first?",
    o: ["Senior secured lenders", "Subordinated bondholders", "Preferred shareholders", "Ordinary shareholders"],
    why: "Priority follows the capital structure: secured senior debt, then unsecured senior, then subordinated, then preferred, then ordinary equity.",
    x: ["Subordinated debt ranks behind senior debt by agreement.", "Preferred shareholders rank behind all debt.", "Ordinary shareholders are last in line."] },
  { id: "cr-03", lv: 3, q: "When is an incurrence covenant tested?",
    o: ["Only when the borrower takes a set action, such as raising new debt", "Every quarter, whatever the borrower does, based on its latest accounts", "Every day, using the borrower's closing cash balance and share price", "Only at maturity, when the lenders check whether they can be repaid"],
    why: "Incurrence covenants, typical of high-yield bonds, only bite when the company does something. Maintenance covenants are tested every quarter.",
    x: ["Quarterly testing describes maintenance covenants, typical of bank loans.", "Covenants aren't tested daily.", "Maturity isn't a covenant test date."] },
  { id: "cr-04", lv: 2, q: "What makes a leveraged loan 'covenant-lite'?",
    o: ["It has no maintenance financial covenants", "It pays no cash interest until maturity", "It is unsecured and ranks behind the bonds", "It has a shorter maturity than other loans"],
    why: "Cov-lite loans keep only incurrence-style protections, giving borrowers more room before lenders can act.",
    x: ["They pay interest like any loan.", "Cov-lite loans are usually still secured.", "Maturity isn't what defines cov-lite."] },
  { id: "cr-05", lv: 1, trap: ["sign", null, null], q: "When market interest rates rise, the price of an existing fixed-rate bond:",
    o: ["Falls", "Rises", "Stays the same", "Rises, but only if the bond is callable"],
    why: "Its fixed coupon is now less attractive than new bonds, so the price falls until its yield matches the market.",
    x: ["Bond prices move opposite to yields.", "Fixed-rate bond prices respond to market rates.", "Callability caps gains when rates fall; it doesn't make prices rise when rates rise."] },
  { id: "cr-06", lv: 2, q: "Which bond is most sensitive to a change in interest rates?",
    o: ["A 30-year zero-coupon bond", "A 2-year bond paying an 8% coupon", "A floating rate note", "A 5-year bond paying a 5% coupon"],
    why: "Duration rises with maturity and falls with coupon. A long zero-coupon bond's duration equals its full maturity.",
    x: ["Short maturity and a high coupon mean low duration.", "Floating rate notes reset their coupons, so their price barely moves.", "Medium maturity and coupon give medium duration."] },
  { id: "cr-07", lv: 1, trap: ["sign", null, "sign"], q: "A company's credit spread widens. What is the most likely cause?",
    o: ["Investors see a higher risk of default", "The company's credit rating was upgraded", "Government bond yields fell", "The company issued equity to repay debt"],
    why: "The spread is the extra yield over government bonds that compensates for credit risk. More perceived risk means a wider spread.",
    x: ["An upgrade signals lower risk, so spreads tighten.", "Spreads are measured over government yields; falling base rates don't widen them on their own.", "Repaying debt with equity usually tightens spreads."] },
  { id: "cr-08", lv: 1, q: "What is the lowest investment-grade credit rating?",
    o: ["BBB− at S&P and Fitch, Baa3 at Moody's", "A− at S&P and Fitch, A3 at Moody's", "BB+ at S&P and Fitch, Ba1 at Moody's", "AAA at S&P and Fitch, Aaa at Moody's"],
    why: "Below BBB−/Baa3 is high yield, which many investors aren't allowed to hold.",
    x: ["A− is well within investment grade, but BBB ratings count too.", "BB+ is the highest high-yield rating.", "AAA is the top rating; only a handful of issuers have it."] },
  { id: "cr-09", lv: 2, trap: ["inverted", null, null], q: "What is a 'fallen angel'?",
    o: ["A bond downgraded from investment grade to high yield", "A bond upgraded from high yield to investment grade", "A company that recovered and refinanced after defaulting", "A new bond priced below par because demand was weak"],
    why: "Fallen angels often face forced selling by investment-grade-only funds, which can push prices below fundamental value.",
    x: ["An upgrade to investment grade is a 'rising star'.", "Recovery after default is a separate situation.", "Pricing below par is an original issue discount."] },
  { id: "cr-10", lv: 1, trap: ["wrong-measure", "wrong-measure", "wrong-measure"], q: "How is an interest coverage ratio calculated?",
    o: ["EBITDA or EBIT ÷ interest expense", "Total debt ÷ shareholders' equity", "Interest expense ÷ total revenue", "Net debt ÷ EBITDA for the last year"],
    why: "Coverage shows how many times operating earnings cover interest. Below about 2x lenders start to worry.",
    x: ["Debt ÷ equity is gearing.", "That's interest as a share of sales.", "Net debt ÷ EBITDA is leverage."] },
  { id: "cr-11", lv: 2, q: "What is a unitranche loan?",
    o: ["A single loan combining senior and junior debt at one blended rate", "Two separate loans from different lenders, one senior and one junior", "An equity instrument that pays a fixed dividend like a loan would", "A government-guaranteed loan for small and mid-sized companies"],
    why: "Common in direct lending: one lender group, one document and one price, which is faster and simpler than a senior plus mezzanine structure.",
    x: ["Unitranche replaces separate tranches with one facility.", "It's debt, not equity.", "It's private credit, not government-backed."] },
  { id: "cr-12", lv: 3, q: "What is a make-whole call on a bond?",
    o: ["The issuer can repay early by paying the value of the remaining payments", "Investors can force the issuer to repay at par if its credit rating falls", "The issuer can repay at par at any time, without paying any premium", "Investors can convert the bond into shares at a preset conversion price"],
    why: "The make-whole compensates investors for lost coupons, so redeeming early is expensive and mainly used around M&A or refinancings.",
    x: ["An investor's right to sell back is a put.", "Repaying at par any time would be a cheap call, not a make-whole.", "Conversion into shares is a convertible feature."] },
  { id: "cr-13", lv: 2, q: "Why does a convertible bond pay a lower coupon than an otherwise identical straight bond?",
    o: ["Investors receive an option to convert into equity", "Convertibles are always secured on the issuer's assets", "Convertibles always have shorter maturities than straight bonds", "Convertibles carry no default risk, as they can become shares"],
    why: "Investors accept a lower coupon in exchange for the embedded call option on the issuer's shares.",
    x: ["Convertibles are usually unsecured.", "Maturity isn't the reason; the option is.", "Convertibles can default like any bond."] },
  { id: "cr-14", lv: 1, q: "In a default, which instrument typically has the highest recovery rate?",
    o: ["Senior secured loans", "Subordinated bonds", "Senior unsecured bonds", "Ordinary shares"],
    why: "Collateral and seniority mean secured loans historically recover far more than unsecured or subordinated debt.",
    x: ["Subordinated debt recovers the least among debt instruments.", "Unsecured bonds rank behind secured lenders.", "Shareholders typically recover nothing."] },
  { id: "cr-15", lv: 1, trap: ["wrong-measure", "concept", "inverted"], q: "A company has a US$200m revolving credit facility and has drawn US$50m. What does it typically pay on the facility?",
    o: ["Interest on the US$50m drawn, plus a commitment fee on the US$150m undrawn", "Interest on the full US$200m, whether or not the money has been drawn", "Nothing until the facility is fully drawn, then interest on all US$200m", "A commitment fee on the US$50m drawn, and nothing at all on the US$150m undrawn"],
    why: "A revolver works like a corporate credit card: the company draws, repays and redraws as needed. It pays interest (base rate + margin) only on what it has drawn, and a smaller commitment fee, often 0.25–0.50% a year, on the undrawn amount for keeping the money available.",
    x: ["Interest is charged only on the amount drawn.", "The lender charges a commitment fee for keeping the undrawn money available.", "It's the other way round: the drawn part pays interest and the undrawn part pays the commitment fee."] },
  { id: "cr-16", lv: 2, trap: ["inverted", "concept", "wrong-measure"], q: "How does a term loan B (TLB) typically differ from a term loan A (TLA)?",
    o: ["A TLB goes to institutional investors and barely amortises; a TLA amortises heavily", "A TLA goes to institutional investors and barely amortises; a TLB stays with banks", "A TLB is always unsecured, so it ranks behind the TLA and pays a higher margin", "A TLB pays a fixed coupon like a bond, while a TLA pays a floating rate"],
    why: "Banks keep TLAs and revolvers, which have shorter maturities and large scheduled repayments. TLBs are syndicated to CLOs and loan funds, run longer (often seven years) and repay about 1% a year with a bullet at maturity, usually at a slightly higher margin.",
    x: ["It's the other way round: institutional investors buy TLBs, and banks keep the amortising TLA.", "TLAs and TLBs usually share the same first-lien security.", "Both are usually floating-rate, priced at SOFR plus a margin."] },
  { id: "cr-17", lv: 2, trap: ["inverted", "concept", "concept"], q: "How does an asset-based loan (ABL) differ from a cash-flow loan?",
    o: ["It's sized on a borrowing base of receivables and inventory, not a multiple of EBITDA", "It's sized as a multiple of EBITDA, with leverage covenants tested every quarter", "It's unsecured, so it's sized on the borrower's credit rating rather than its assets", "It can only be used to buy new assets, which then become the lender's security"],
    why: "An ABL lender advances a percentage of eligible collateral, for example 85% of receivables and 50–65% of inventory, and availability moves with those balances. That suits asset-heavy businesses with volatile earnings, such as retailers and distributors. Cash-flow loans are sized on EBITDA instead.",
    x: ["That describes a cash-flow loan.", "ABLs are secured on the assets that make up the borrowing base.", "An ABL is a working capital facility; the money can be used for general corporate purposes."] },
  { id: "cr-18", lv: 2, trap: ["inverted", "concept", "concept"], q: "A first-lien loan and a second-lien loan are secured on the same assets. What's the difference?",
    o: ["First-lien lenders are repaid in full from the collateral before second-lien lenders", "Second-lien lenders are repaid first from the collateral, because their loan is newer", "They share the collateral equally, each in proportion to the size of its loan", "The second-lien loan has no security at all, so it ranks with unsecured creditors"],
    why: "Liens set the order of claims on the same collateral, with the details in an intercreditor agreement. Because second-lien lenders only get what's left of the collateral, they charge a higher margin. As far as the collateral goes, both still rank ahead of unsecured creditors.",
    x: ["Priority depends on the lien ranking, not on which loan is newer.", "Sharing equally (pari passu) is what two first-lien loans would do.", "Second-lien debt is secured, just behind the first lien."] },
  { id: "cr-19", lv: 3, trap: ["concept", "concept", "wrong-measure"], q: "A holding company has issued bonds and its operating subsidiary has bank loans. Neither guarantees the other. If the subsidiary fails, who is repaid first from its assets?",
    o: ["The subsidiary's lenders; the bondholders only get what's left for its shareholder", "The holding company's bondholders, because the bonds are larger than the loans", "Both rank equally, sharing the subsidiary's assets in proportion to their claims", "Whoever's debt matures first, since earlier maturities are repaid first"],
    why: "Holding company creditors have a claim on the holding company, whose main asset is its shares in the subsidiary. The subsidiary's own creditors are paid first from its assets, and only the equity left over flows up. That's structural subordination; guarantees from the subsidiary are the usual fix.",
    x: ["Size doesn't set priority; where the debt sits in the group does.", "They're claims on different companies, so they don't rank equally against the subsidiary's assets.", "Maturity doesn't change priority in an insolvency."] },
  { id: "cr-20", lv: 1, trap: ["wrong-measure", "wrong-measure", "inverted"], q: "A leveraged loan is priced at SOFR + 3.50%. What does that mean for the borrower?",
    o: ["Its rate resets with SOFR, plus a fixed 3.50% margin", "It pays a fixed 3.50% for the life of the loan, whatever SOFR does", "It pays SOFR only if SOFR is above 3.50%, and nothing below that", "The lender pays the borrower 3.50% above SOFR on the loan balance"],
    why: "SOFR, the US overnight benchmark rate, moves with the Fed's policy rate; the margin reflects the borrower's credit risk. Floating rates protect lenders when rates rise, so borrowers often hedge with swaps or caps. Loans often also have a SOFR floor.",
    x: ["The 3.50% is only the margin over the benchmark.", "That would be a floor, which is a separate feature.", "The borrower pays interest to the lender, not the reverse."] },
  { id: "cr-21", lv: 2, trap: ["concept", "inverted", "wrong-measure"], q: "A bond with a 5% coupon trades at 90. How do its current yield and yield to maturity compare?",
    o: ["Current yield is about 5.6%; YTM is higher, as the price rises to par", "Both equal the 5% coupon, because the coupon is fixed when the bond is issued", "Current yield is about 5.6%; YTM is lower, as the price falls further over time", "Current yield is 4.5% and YTM is 5%, the coupon set when the bond was issued"],
    why: "Current yield = coupon ÷ price = 5 ÷ 90 = 5.6%. It ignores the 10-point gain as the bond is repaid at 100. YTM includes it, so for a bond below par YTM > current yield > coupon. Above par it's the reverse.",
    x: ["The coupon is fixed on face value; the yields depend on the price paid.", "Below par, the pull to 100 adds to the return, so YTM is higher, not lower.", "That multiplies the coupon by the price instead of dividing by it."] },
  { id: "cr-22", lv: 3, trap: ["concept", "inverted", "wrong-measure"], q: "A callable bond trades well above par. Which yield do investors usually quote for it?",
    o: ["Yield to worst: the lowest of the yields to maturity and to each call date", "Yield to maturity, because the issuer can't repay the bond before it matures", "The highest of the possible yields, to show investors the best case", "The coupon rate, because that's what the bond pays each year"],
    why: "Above par, the issuer is likely to call the bond as soon as it can refinance more cheaply, so the investor loses the premium sooner. The yield to that call date is then below the yield to maturity, so the conservative yield to worst is quoted.",
    x: ["A callable bond can be repaid early; that's the risk being priced.", "Investors assume the issuer acts in its own interest, which is the worst case for them.", "The coupon ignores the price paid."] },
  { id: "cr-23", lv: 2, trap: ["inverted", "concept", "wrong-measure"], q: "What is the difference between Macaulay duration and modified duration?",
    o: ["Macaulay is the weighted-average time to cash flows; modified is price sensitivity", "Modified is the weighted-average time to cash flows; Macaulay is price sensitivity", "They're always the same number, just quoted in years rather than in percent", "Macaulay duration applies only to zero-coupon bonds; modified to all others"],
    why: "Macaulay duration, in years, weights each cash flow's timing by its share of the price. Dividing it by (1 + yield per period) gives modified duration, roughly the % price fall for a one-point rise in yield. For a zero-coupon bond, Macaulay duration equals the maturity.",
    x: ["It's the other way round.", "They differ by the factor (1 + yield), so modified duration is slightly smaller.", "It applies to any bond; for a zero-coupon bond it simply equals the maturity."] },
  { id: "cr-24", lv: 3, trap: ["sign", "inverted", "concept"], q: "Why does a callable bond show negative convexity when yields fall?",
    o: ["Its price gains flatten out near the call price, as a call becomes likely", "Its price falls when yields fall, because the issuer is likely to call it", "Its duration rises sharply as yields fall, so its price gains speed up", "Callable bonds have no interest rate risk, so their prices can't rise"],
    why: "A plain bond has positive convexity: as yields fall, its price rises at an accelerating rate. A callable bond's price is capped near the call price, because investors expect to be repaid there, so the price–yield curve bends the other way. Mortgage-backed securities behave similarly because borrowers refinance.",
    x: ["The price still rises when yields fall, just by less and less.", "It's the opposite: effective duration shortens as a call becomes likely.", "Callable bonds still lose value when yields rise."] },
  { id: "cr-25", lv: 2, trap: ["inverted", "wrong-measure", "concept"], q: "A term loan is issued at 98, an original issue discount (OID) of 2 points. What does that mean?",
    o: ["The borrower gets 98 for every 100 it must repay, raising the lender's yield", "The lender receives 98 for every 100 it lends, so the borrower pays less", "The loan's margin is 2% lower than it would be at par, to balance the price", "The borrower repays only 98 at maturity, saving 2 points on the loan"],
    why: "OID is an upfront discount, a way to raise the yield without changing the margin. On a loan expected to last about four years, 2 points of OID adds roughly 0.5% a year. Arrangers use it to clear the market when demand is weak.",
    x: ["The lender pays 98 and is repaid 100; it's the borrower who receives less than face value.", "The margin doesn't change; the discount is separate and adds to the yield.", "The full 100 is repaid at maturity; that's where the extra return comes from."] },
  { id: "cr-26", lv: 2, trap: ["concept", "concept", "inverted"], q: "Why does mezzanine debt often come with warrants (an 'equity kicker')?",
    o: ["To give lenders some equity upside for ranking behind the senior debt", "To make the mezzanine loan rank ahead of the bank debt in an insolvency", "Because mezzanine debt pays no interest, so the warrants are its only return", "So the borrower can repay the loan in shares at any time it chooses"],
    why: "Mezzanine sits between senior debt and equity, so it carries more risk. Lenders are paid with a mix of cash interest, PIK interest and warrants, targeting returns well above senior debt but below equity.",
    x: ["Warrants don't change the ranking; mezzanine stays subordinated.", "Mezzanine pays interest, often partly in cash and partly PIK.", "Warrants give the lender a right to buy shares; they don't let the borrower repay in shares."] },
  { id: "cr-27", lv: 2, trap: ["concept", "wrong-measure", "concept"], q: "In an acquisition, why does a buyer often sign a bridge loan commitment alongside the purchase agreement?",
    o: ["To show the seller it has committed funding, refinanced later by bonds or loans", "Because bridge loans are the cheapest long-term financing a buyer can get", "To pay the advisers' fees on signing, before the main financing is in place", "Because sellers must lend part of the price back to the buyer until the deal completes"],
    why: "The bond or loan deal usually can't be done before signing, so banks commit to a short-term bridge facility. It's rarely drawn: the buyer raises permanent financing before completion, pushed by the bridge's fees and rising rates. UK takeovers require 'certain funds' before a cash offer is announced.",
    x: ["Bridges are expensive by design, with step-up rates and fees, so they're refinanced quickly.", "Fees are paid from the buyer's own resources; that isn't the bridge's role.", "Seller financing (a vendor note) is a different instrument."] },
  { id: "cr-28", lv: 2, trap: ["inverted", "concept", "concept"], q: "Compared with high-yield bonds, leveraged loans typically:",
    o: ["Pay a floating rate, are secured and can be repaid early at or near par", "Pay a fixed coupon and have long non-call periods that protect investors", "Are unsecured and rank behind the bonds, so they pay a higher margin", "Can't be traded once they're issued, so lenders hold them to maturity"],
    why: "Leveraged loans (TLBs) are usually senior secured, float at SOFR plus a margin and can be repaid at par after a short soft-call period. High-yield bonds are usually fixed-rate, often unsecured, with non-call periods and call premiums, and they carry incurrence covenants.",
    x: ["That describes high-yield bonds.", "Loans are usually senior secured and rank ahead of unsecured bonds.", "Loans trade actively in the secondary market, though they settle more slowly than bonds."] },
  { id: "cr-29", lv: 2, trap: ["inverted", "concept", "concept"], q: "In a sell-side auction, what is 'staple financing'?",
    o: ["A debt package arranged on the seller's side and offered to every bidder", "A loan the seller makes to the winning bidder to fund part of the price", "A bridge loan the winning bidder has to take from the target's own banks", "Debt the target has to repay in full at completion, before the sale closes"],
    why: "The seller's adviser (or its lending arm) arranges a financing package in advance, 'stapled' to the sale documents. It sets a floor for leverage, speeds up the process and helps smaller bidders, which supports the price. Bidders can use it or bring their own. The catch: the adviser earns fees on both sides, a conflict the seller has to manage.",
    x: ["That's a vendor loan (seller note): the seller itself lends.", "Bidders aren't obliged to use it. They can bring their own financing.", "That describes existing debt being repaid at completion."] },
  { id: "cr-30", lv: 2, trap: ["wrong-measure", "concept", "inverted"], q: "How does a fixed charge cover ratio usually differ from interest cover?",
    o: ["It adds scheduled debt repayments (and often rent) to the interest it must cover", "It uses net income instead of EBITDA, so tax and depreciation come off first", "It counts only fixed-rate debt, leaving floating-rate loans out of the test", "It divides interest by EBITDA, so a lower figure means the company is safer"],
    why: "Interest cover asks whether earnings cover the interest. Fixed charge cover asks whether cash flow covers all the payments the company can't avoid: interest plus scheduled principal repayments, and often lease or rent costs, usually after capex and cash taxes. Definitions vary from one loan agreement to another, so read the definition before comparing.",
    x: ["The top of the ratio is usually a cash measure, such as EBITDA less capex and tax, not net income.", "'Fixed charges' are payments the company has to make, whatever the type of interest rate.", "It's cash flow ÷ charges, so a higher figure is safer."] },
  { id: "cr-31", lv: 2, trap: ["concept", "concept", "concept"], q: "What does a PIK toggle note let the issuer do?",
    o: ["Choose each period to pay interest in cash or add it to the debt, at a higher rate", "Switch the interest between fixed and floating rates whenever market rates fall", "Convert the notes into shares if its share price rises above a set level", "Delay repaying the principal at maturity by up to five more years"],
    why: "Payment-in-kind (PIK) interest is added to the amount owed instead of being paid in cash. A toggle lets the issuer choose each period, and the PIK option usually carries a higher rate. It protects cash in a tight year, but the debt keeps growing, so lenders read a switch to PIK as a warning sign.",
    x: ["That would be done with an interest rate swap, not a toggle.", "That's a convertible bond.", "That's an extension option. A toggle is about how interest is paid."] },
  { id: "cr-32", lv: 2, trap: ["concept", "concept", "inverted"], q: "Why might a private equity sponsor choose a direct lender (a private credit fund) over a syndicated leveraged loan?",
    o: ["More certainty and speed, private terms and fewer lenders, at a higher margin", "Direct loans are always cheaper, as credit funds have lower costs than banks", "Direct lenders never ask for financial covenants of any kind in their loans", "Direct loans trade freely in the market, so they're easier to refinance later"],
    why: "A direct lender (or a small club of them) holds the loan itself, so the terms are agreed privately and quickly, with no risk of a failed syndication. It can also offer flexible features, such as delayed-draw tranches or part of the interest paid in kind. The price is usually a higher margin, and often a maintenance covenant. Syndicated loans are cheaper and can be larger, but depend on market conditions when they launch.",
    x: ["They usually cost more: the higher margin pays for certainty and flexibility.", "Direct loans often keep a maintenance covenant, unlike most covenant-lite syndicated loans.", "Direct loans are usually held to maturity. It's syndicated loans that trade."] },
  { id: "cr-33", lv: 2, trap: ["concept", "concept", "concept"], q: "In a buy-and-build strategy, why might a sponsor's financing include a delayed draw term loan?",
    o: ["It commits funding now for bolt-on deals, to be drawn as they're done", "It lets the company postpone its first interest payment by a year", "It's drawn on day one but repaid once all the bolt-on deals are done", "It replaces the revolver, so no working capital line is needed"],
    why: "A delayed draw term loan is a committed facility the borrower can draw over a set period (often one to two years), typically for acquisitions or capex. The sponsor knows the money is there for bolt-ons without paying interest on it upfront. Lenders usually charge a ticking fee on the undrawn amount and set conditions for each draw, such as a leverage test.",
    x: ["Interest starts when the money is drawn. It doesn't delay interest on debt already drawn.", "It's drawn later, as deals happen, not on day one.", "The revolver still funds day-to-day working capital. A delayed draw term loan funds specific uses."] },
  { id: "cr-34", lv: 2, q: "What does an excess cash flow sweep in a leveraged loan require?",
    o: ["Part of each year's surplus cash goes to repay the loan early", "All cash above a set minimum is held in a blocked bank account", "The margin steps up each year the company holds surplus cash", "Surplus cash is paid to the sponsor as a dividend each year"],
    why: "A set share of each year's excess cash flow, often 50% stepping down to 25% and 0% as leverage falls, goes to prepay the term loans. It speeds up deleveraging when the business does well.",
    x: ["The cash isn't locked away; it's used to repay debt.", "Margins can step down as leverage falls (a margin ratchet), but the sweep is about repayment, not pricing.", "Dividends are usually restricted by the loan, not required."] },
  { id: "cr-35", lv: 2, trap: ["wrong-measure", "missed-step", "concept"], q: "Excess cash flow is US$40m. The loan sweeps 50% of it when leverage is above 4.0x, 25% between 3.0x and 4.0x, and nothing below 3.0x. Leverage is 3.6x. How much must be prepaid?",
    o: ["US$10m", "US$20m", "US$40m", "Nothing"],
    why: "At 3.6x the 25% step applies: 25% × 40 = US$10m. Had leverage stayed above 4.0x, it would have been US$20m.",
    x: ["That's the 50% rate, which applies only above 4.0x.", "The sweep takes a share of excess cash flow, not all of it.", "Nothing is swept only below 3.0x; at 3.6x the 25% step applies."] },
  { id: "cr-36", lv: 2, trap: ["concept", "wrong-measure", "concept"], q: "A term loan has six months of 101 soft call protection. Four months after closing, the borrower refinances it at a lower margin. What does it pay?",
    o: ["101% of the amount repaid: a 1% premium", "Par, since soft call protection only applies to bonds", "A make-whole: the present value of the interest lost", "102% of the amount repaid, the usual first-year rate"],
    why: "A soft call charges 1% if the loan is refinanced or repriced to a lower margin during the protection period, here six months. After that, the loan can be repaid at par.",
    x: ["Soft call protection is a loan feature; bonds have non-call periods and call premiums.", "A make-whole is a bond feature and costs far more.", "A 102/101 schedule is a hard call, more common in private credit; a soft call is 101."] },
  { id: "cr-37", lv: 2, trap: ["inverted", "wrong-measure", "inverted"], q: "A company has net debt of US$300m and EBITDA of US$75m. Its covenant caps leverage at 5.0x. With debt unchanged, how far can EBITDA fall before a breach?",
    o: ["20%", "25%", "1.0x", "80%"],
    why: "Leverage today = 300 ÷ 75 = 4.0x. The covenant is hit when EBITDA = 300 ÷ 5.0 = US$60m, a fall of 15 ÷ 75 = 20%. Or: 1 − 4.0 ÷ 5.0 = 20%.",
    x: ["That's how far debt could rise with EBITDA unchanged: (5.0 − 4.0) ÷ 4.0.", "That's the gap in turns of leverage, not the fall in EBITDA.", "That's the EBITDA at the breach as a share of today's, not the fall."] },
  { id: "cr-38", lv: 2, trap: ["wrong-measure", "wrong-measure", "concept"], q: "Net debt is US$480m and EBITDA has fallen to US$90m, against a 5.0x leverage covenant. The sponsor's equity cure is used to repay debt. How much equity does it need to put in?",
    o: ["US$30m", "US$90m", "US$450m", "US$6m"],
    why: "The covenant allows net debt of 5.0 × 90 = US$450m. Net debt is US$480m, so US$30m of new equity, used to repay debt, brings leverage back to 5.0x.",
    x: ["That's EBITDA itself, not the excess debt.", "That's the debt the covenant allows, not the amount to repay.", "That's what an equity cure counted as extra EBITDA would need (480 ÷ 5.0 − 90 = 6); here the cure repays debt."] },
  { id: "cr-39", lv: 2, q: "A company misses a payment on a small bilateral loan. Why might its main term loan also go into default?",
    o: ["A cross-default clause makes a default on other debt a default here too", "All of its loans share one security package, so they default together by law", "Rating agencies are told of the missed payment, which cancels the term loan", "The term loan's margin resets after any missed payment, which is a default"],
    why: "Lenders don't want to wait while other creditors act first, so a default on other debt above a set size counts as a default under their loan too. That's why one small default can spread through a whole capital structure.",
    x: ["Shared security doesn't make loans default together; the cross-default clause does.", "Ratings can fall, but that doesn't cancel a loan.", "Some loans charge default interest, but that's a result of a default, not the cause."] },
  { id: "cr-40", lv: 2, q: "After an event of default, who usually decides whether to accelerate a syndicated loan?",
    o: ["A majority of the lenders, acting through the agent", "Any single lender, for its own share of the loan", "The borrower's auditors, once they flag the default", "A court, which has to approve it before it happens"],
    why: "Syndicated lenders act together: the agent accelerates the loan, demanding immediate repayment, when a majority of lenders tell it to. That stops one lender from pulling the company down alone.",
    x: ["Lenders in a syndicate give up acting alone in exchange for acting together.", "Auditors can raise doubts about the company, but they have no power over the loan.", "Acceleration is a contractual right; no court approval is needed."] },
  { id: "cr-41", lv: 2, q: "Which change to a syndicated loan usually needs the consent of every lender affected?",
    o: ["Cutting the margin or delaying a repayment", "Waiving a breach of the leverage covenant", "Resetting the covenant levels for next year", "Allowing an acquisition the loan would block"],
    why: "Changes to the money terms (amount, margin, maturity, repayment dates) need every affected lender. Covenant waivers, resets and most consents need only a majority, usually 50% in the US and 66⅔% in Europe.",
    x: ["Covenant waivers usually need a majority of lenders, not all of them.", "Covenant resets are a majority decision too.", "Consents to deals the loan restricts are usually a majority decision."] },
  { id: "cr-42", lv: 2, q: "Under an intercreditor agreement, what does payment blockage do after a senior default?",
    o: ["Stops payments to the junior lenders for a period", "Stops the senior lenders enforcing for a period", "Adds the junior lenders' interest to the senior loan", "Lets the junior lenders run the enforcement instead"],
    why: "While a senior default continues, the company can't pay the junior lenders, so cash stays with the senior lenders. The blockage is usually limited, for example to a set number of days a year.",
    x: ["It's the juniors who are held back: a standstill stops them enforcing.", "Junior interest isn't moved into the senior loan; it's simply not paid.", "The senior lenders control enforcement, not the juniors."] },
  { id: "cr-43", lv: 2, q: "Why does an intercreditor agreement put junior lenders on a standstill?",
    o: ["So senior lenders control enforcement first, without a junior rushing in", "So junior lenders keep receiving interest while the senior lenders enforce", "So the borrower gets time to refinance before any lender takes action", "So junior lenders can buy the senior debt at a discount in the meantime"],
    why: "For a set period, often a few months, junior lenders can't accelerate or enforce. The senior lenders, who have most at stake in the assets, decide what happens first.",
    x: ["Payment blockage usually stops junior interest at the same time.", "The standstill protects the senior lenders, not the borrower.", "Juniors can often buy out the senior debt, but at par, and that isn't the purpose of the standstill."] },
  { id: "cr-44", lv: 1, q: "A mezzanine lender receives a US$5m payment that the intercreditor agreement blocked. What must it do?",
    o: ["Hand it over to the senior lenders", "Keep it, and take it off later interest", "Return it to the company as a reserve", "Keep it, since the borrower chose to pay"],
    why: "Under the turnover clause, anything a junior lender receives out of turn is held for the senior lenders and passed to them. It keeps the agreed order of payment intact.",
    x: ["Offsetting it against later interest would still pay the junior out of turn.", "Turnover goes to the senior lenders, not back to the company.", "The borrower can't override the order the lenders agreed between themselves."] },
  { id: "cr-45", lv: 3, trap: ["missed-step", "missed-step", "concept"], q: "An enforcement sale raises US$420m. Costs are US$12m, the super senior revolver US$40m, the senior term loan US$300m and the second-lien loan US$120m. What do second-lien lenders recover per dollar?",
    o: ["About 57 cents", "About 90 cents", "About 67 cents", "About 89 cents"],
    why: "In order: costs 12, revolver 40, senior 300, which leaves 420 − 352 = US$68m for the second-lien lenders: 68 ÷ 120 ≈ 57 cents per dollar.",
    x: ["That leaves out the super senior revolver, which is paid before the senior term loan.", "That leaves out the enforcement costs, which come first.", "That shares the money pro rata across all the debt, ignoring the order of payment."] },
  { id: "cr-46", lv: 2, q: "In a distressed sale run by the senior lenders, why can they release the junior debt and its security?",
    o: ["So the buyer takes the company free of debt it isn't taking on", "So that the junior lenders are repaid in full before the sale", "Because junior debt is always written off in any company sale", "So that the junior lenders can block a sale at too low a price"],
    why: "No buyer pays for a company that still carries debt it doesn't want. The release lets the senior lenders sell it clean; juniors are protected by rules on how the sale is run, such as a fair process or an independent valuation.",
    x: ["Juniors are paid only from what's left after the senior lenders.", "Outside an enforcement, junior debt is repaid or transferred, not written off.", "The release does the opposite: it stops juniors blocking the sale."] }
]);

// New-format questions (shown only when "new formats" is on).
Bank.addFormat("credit", [
  { id: "cr-grid-01", lv: 2, type: "grid", q: "Does each feature usually describe a leveraged loan or a high-yield bond?",
    columns: ["Leveraged loan", "High-yield bond"],
    rows: [
      { text: "Pays a floating rate (SOFR + margin)", answer: 0, note: "Loans float; lenders are protected when rates rise." },
      { text: "Pays a fixed coupon", answer: 1, note: "Most high-yield bonds are fixed-rate." },
      { text: "Can be repaid at par after a short soft-call period", answer: 0, note: "Loans are prepayable, often with a 1% premium for the first six months." },
      { text: "Has a non-call period, then call premiums that step down", answer: 1, note: "Typically non-call for 2–5 years, then premiums falling towards par." },
      { text: "Mostly bought by CLOs and loan funds", answer: 0, note: "CLOs are the biggest buyers of term loan Bs." },
      { text: "Sold to investors under Rule 144A, with an offering memorandum", answer: 1, note: "Bonds are sold through the capital markets, usually to institutional investors under Rule 144A." }
    ],
    why: "Loans: floating-rate, secured, prepayable and largely held by CLOs. Bonds: fixed-rate, call-protected and sold through the capital markets." },
  { id: "cr-ord-01", lv: 1, type: "order", q: "Rank these claims from first to be repaid to last in a typical insolvency.",
    answer: ["First-lien term loan and revolver", "Second-lien term loan", "Senior unsecured notes", "Subordinated notes", "Preferred equity", "Common equity"],
    why: "Secured debt is repaid from its collateral first, in lien order. Unsecured creditors come next, subordinated debt after them, and shareholders last, preferred before common. Real cases can differ, for example through structural subordination or a super-senior revolver." },
  // Walk-through cards: answer out loud, then grade yourself against the model answer.
  { id: "cr-walk-01", lv: 2, type: "walk", q: "How would you assess a company's creditworthiness?",
    points: [
      "Business risk: the industry, competitive position, size, diversification and how cyclical the cash flows are.",
      "Leverage: debt (or net debt) ÷ EBITDA, now and after the proposed financing.",
      "Coverage: EBITDA (or EBIT) ÷ interest, and fixed-charge cover including leases.",
      "Liquidity and maturities: cash, the undrawn revolver and when the debt falls due.",
      "Structure and protection: security, seniority, covenants and guarantees, and the recovery value if things go wrong."
    ],
    why: "Lenders care about two questions: will the company pay, and what do I get back if it doesn't? Cover both." }
]);

// More new formats: answer + reason and spot the error.
Bank.addFormat("credit", [
  { id: "cr-why-01", lv: 2, type: "reason",
    q: "A company with net debt/EBITDA of 4.0x sells a division for exactly 4.0x that division's EBITDA, and uses all the cash to repay debt. What happens to its leverage ratio?",
    answers: ["It stays at 4.0x", "It falls below 4.0x", "It rises above 4.0x"],
    answerNotes: [
      "Debt does fall, but EBITDA falls too, by the same proportion.",
      "It would rise only if the division were sold below 4.0x. At exactly 4.0x, the two effects cancel out."],
    reasons: [
      "Debt and EBITDA both fall by the same proportion, so the ratio holds",
      "Repaying debt always lowers leverage, because less debt is owed",
      "The company loses EBITDA, so each dollar of debt is covered by less profit",
      "Leverage covenants ignore asset sales, so the reported ratio doesn't move"],
    reasonNotes: [
      "Not if EBITDA falls too. Leverage is a ratio, so both sides matter.",
      "EBITDA falls, but debt falls by the same proportion, so the cover per dollar of debt is unchanged.",
      "Asset sales do change both parts of the ratio. Here they just move in proportion."],
    why: "Say EBITDA is US$100m and net debt US$400m (4.0x). Selling a division with US$20m of EBITDA for 4.0x raises US$80m, which repays debt: net debt becomes US$320m and EBITDA US$80m, still 4.0x. Selling above the company's own leverage multiple reduces leverage; selling below it increases leverage." },

  { id: "cr-why-02", lv: 2, type: "reason",
    q: "A company has two bonds maturing on the same day: one senior secured, one subordinated. Which usually trades at the higher yield?",
    answers: ["The subordinated bond", "The senior secured bond", "Both trade at the same yield"],
    answerNotes: [
      "Security makes the senior bond safer, so it needs a lower yield, not a higher one.",
      "The chance of default is the same, but recovery isn't: the subordinated bond loses more in a default, so it pays more."],
    reasons: [
      "It's repaid after the senior debt in a default, so investors expect to recover less",
      "Secured bondholders have to monitor the collateral, so they demand a higher return",
      "The same company is behind both, so the default risk and the yield are identical",
      "Subordinated bonds default more often than senior bonds of the same company"],
    reasonNotes: [
      "Security lowers risk, so secured lenders accept a lower return, monitoring or not.",
      "Default risk is the same, but the loss in a default isn't, and investors price both.",
      "Both bonds default together: if the company fails, both stop paying. The difference is how much each recovers afterwards."],
    why: "Both bonds default at the same time, because the same company stands behind them. What differs is recovery: secured debt is repaid from its collateral first, while subordinated debt is paid only after the senior claims. Expected loss = chance of default × loss when it happens, and the subordinated bond loses more, so investors demand a higher yield." },

  { id: "cr-spot-01", lv: 1, type: "spot",
    q: "A company has EBITDA of US$200m, debt of US$900m, cash of US$100m and yearly interest of US$60m. A candidate checks two covenants: net debt/EBITDA of at most 4.5x, and interest cover of at least 3.0x. Which line contains the mistake?",
    lines: [
      "Net debt: US$900m − US$100m = US$800m",
      "Leverage: US$800m ÷ US$200m = 4.0x, inside the 4.5x limit",
      "Interest cover: US$60m ÷ US$200m = 0.3x",
      "0.3x is below the 3.0x minimum, so the cover covenant is breached"],
    wrong: 2,
    lineNotes: [
      "Net debt is debt less cash. That's right.",
      "Net debt ÷ EBITDA = 4.0x, below the 4.5x cap, so the test passes. That's right.",
      null,
      "The comparison is right, but it uses the upside-down ratio from line 3, so the conclusion is wrong."],
    fixes: [
      "Divide EBITDA by interest: 200 ÷ 60 = 3.3x, so the cover test passes",
      "Use net debt instead of interest: 800 ÷ 200 = 4.0x, so it passes",
      "Use gross debt: interest cover is 900 ÷ 200 = 4.5x, right at the limit",
      "Compare interest with cash: 60 ÷ 100 = 0.6x, so the test fails"],
    fixNotes: [
      "That's the leverage ratio again. Interest cover compares profit with the interest bill.",
      "Debt isn't part of interest cover: it compares EBITDA with interest.",
      "Interest cover measures how many times profit covers interest, not cash."],
    why: "Interest cover = EBITDA ÷ interest: how many times profit covers the interest bill. Here 200 ÷ 60 = 3.3x, above the 3.0x minimum, so both covenants pass. Flipping a ratio upside down is easy under time pressure. A quick sense check helps: a healthy company's profit should be several times its interest." },

  { id: "cr-spot-02", lv: 2, type: "spot",
    q: "A loan agreement defines fixed charge cover as (EBITDA − capex − cash taxes) ÷ (cash interest + scheduled debt repayments), with a minimum of 1.2x. The borrower has EBITDA of US$100m, capex of US$20m, cash taxes of US$10m, cash interest of US$30m and scheduled repayments of US$25m. A candidate tests the covenant. Which line contains the mistake?",
    lines: [
      "Cash flow available: 100 − 20 − 10 = US$70m",
      "Fixed charges: cash interest of US$30m",
      "Fixed charge cover: 70 ÷ 30 = 2.33x",
      "Against the 1.2x minimum: the covenant is met with plenty of room to spare"],
    wrong: 1,
    lineNotes: [
      "Right: EBITDA less capex and cash taxes, as the agreement defines it.",
      null,
      "The division is right, but it uses the charges from line 2.",
      "The conclusion follows from line 3, which carries the mistake: the headroom is much smaller."],
    fixes: [
      "Add the US$25m of repayments: 70 ÷ 55 = 1.27x, so the test is only just met",
      "Use EBITDA alone as cash flow: 100 ÷ 30 = 3.33x, comfortably above the minimum",
      "Deduct the repayments from cash flow: 45 ÷ 30 = 1.50x, still above the minimum",
      "Add repayments and capex to the charges: 70 ÷ 75 = 0.93x, so the test is breached"],
    fixNotes: [
      "The agreement deducts capex and cash taxes first, and line 1 does that correctly.",
      "Repayments belong with the charges being covered, not taken off the cash flow.",
      "Capex is already deducted in line 1, so adding it to the charges counts it twice."],
    why: "Fixed charge cover tests whether cash flow covers every fixed payment, so scheduled repayments count alongside interest: (100 − 20 − 10) ÷ (30 + 25) = 70 ÷ 55 = 1.27x. The covenant is met, but with little headroom: a fall of about US$4m in cash flow would breach it." }
]);

// Loan agreements and the intercreditor agreement (added 2026-11-26).
Bank.addFormat("credit", [
  { id: "cr-walk-02", lv: 2, type: "walk", q: "Walk me through the key terms of a leveraged loan.",
    points: [
      "Pricing and repayment: a margin over SOFR, often a small discount at issue, and for a term loan B about 1% a year with the rest repaid at maturity.",
      "Mandatory prepayments: part of excess cash flow (stepping down as leverage falls), asset sale proceeds and a change of control; voluntary prepayment at par after a short 101 soft call.",
      "Covenants: a maintenance leverage covenant tested quarterly with headroom to the plan and an equity cure, or only incurrence covenants if it's covenant-lite.",
      "Events of default (non-payment, covenant breach, cross-default, insolvency) let a majority of lenders accelerate; money terms can only change with every affected lender.",
      "Security and guarantees from the main companies, and an intercreditor agreement setting the ranking against any second-lien or mezzanine debt."
    ],
    why: "Group the terms by what they protect: getting paid (pricing, prepayments), early warning (covenants), what lenders can do (defaults, acceleration) and what they recover (security, intercreditor)." },

  { id: "cr-why-03", lv: 2, type: "reason",
    q: "A sponsor-backed company will narrowly breach its leverage covenant next quarter. Trading is otherwise solid. What usually happens?",
    answers: ["A waiver or amendment, for a fee or a higher margin", "The lenders accelerate and take over the company", "The company files for insolvency to protect itself", "Nothing: a breach matters only once a payment is missed"],
    answerNotes: [
      "Lenders can, but rarely want to: running a company isn't their business, and a forced sale would lose value.",
      "Insolvency would destroy value for everyone; a narrow breach in a solid business is fixed by negotiation.",
      "A covenant breach is an event of default in its own right, once any cure period passes."],
    reasons: [
      "Lenders rarely want the company; the breach gives them leverage to reprice",
      "A breach lets lenders enforce, so they usually take control at once",
      "Insolvency protection stops the lenders from acting on the breach",
      "Only a missed payment counts as an event of default under a loan"],
    reasonNotes: [
      "Being able to enforce isn't the same as wanting to: lenders usually prefer a fee and better terms.",
      "Filing is a last resort for a company that can't pay, not a response to a narrow breach.",
      "Covenant breaches, cross-default and insolvency are events of default too."],
    why: "Most covenant breaches end in a negotiation. The sponsor may use an equity cure; otherwise lenders agree a waiver or reset in return for a fee, a higher margin or some debt repaid. The covenant's job is to bring them to the table early." },

  { id: "cr-spot-03", lv: 2, type: "spot",
    q: "An analyst works out covenant headroom. Net debt is US$360m, EBITDA US$90m and the leverage covenant 5.0x. Which line contains the mistake?",
    lines: [
      "Leverage today: 360 ÷ 90 = 4.0x",
      "EBITDA at which leverage hits 5.0x: 360 ÷ 5.0 = US$72m",
      "Headroom in dollars: 90 − 72 = US$18m",
      "As a share of EBITDA: 18 ÷ 72 = 25%",
      "So EBITDA can fall 25% before a breach"],
    wrong: 3,
    lineNotes: [
      "Right: net debt ÷ EBITDA.",
      "Right: the EBITDA at which net debt is exactly 5.0 times EBITDA.",
      "Right: EBITDA can fall by US$18m.",
      null,
      "The wording is right, but it carries forward the mistake from line 4."],
    fixes: [
      "Divide by today's EBITDA: 18 ÷ 90 = 20%",
      "Divide by net debt: 18 ÷ 360 = 5%",
      "Use the leverage gap: (5.0 − 4.0) ÷ 4.0 = 25%",
      "Divide by the covenant level: 18 ÷ 5.0 = 3.6%"],
    fixNotes: [
      "Headroom is a fall in EBITDA, so it's measured against EBITDA, not debt.",
      "That's how far debt could rise, not how far EBITDA can fall; it gives the same wrong 25%.",
      "The covenant is a multiple, not an amount of EBITDA."],
    why: "A fall is measured from where you start: US$18m out of today's US$90m is 20%. Check: 1 − 4.0 ÷ 5.0 = 20%." },

  { id: "cr-ord-02", lv: 2, type: "order",
    q: "A company breaches its leverage covenant and nothing is fixed. Put the steps in their usual order.",
    answer: [
      "The quarterly test shows leverage above the covenant",
      "The compliance certificate reports the breach to the lenders",
      "The cure period passes with no equity cure or waiver",
      "An event of default is now continuing",
      "A majority of lenders tell the agent to accelerate the loan",
      "The senior lenders enforce their security while junior lenders stand still"],
    why: "The test and the certificate reveal the breach; the cure period gives the sponsor a chance to fix it. Only then is there a continuing event of default, which lets a majority of lenders accelerate and the senior lenders enforce first." }
]);
